import { DashboardGrid, type DashboardItem } from '@absoluteui/components/dashboard-grid';

const host = document.createElement('div');
for (const [id, title] of [['sales', 'Sales'], ['users', 'Active users'], ['map', 'Regions']] as const) {
  const section = document.createElement('section');
  section.dataset.auiItem = id;
  const heading = document.createElement('h2');
  heading.textContent = title;
  section.append(heading);
  host.append(section);
}
document.body.append(host);

const items: DashboardItem[] = [
  { id: 'sales', x: 0, y: 0, w: 6, h: 2 },
  { id: 'users', x: 6, y: 0, w: 6, h: 2 },
  { id: 'map', x: 0, y: 2, w: 12, h: 3, minH: 2 },
];
const grid = DashboardGrid.create(host, { label: 'Overview', items });
host.dataset.breakpoint = grid.breakpoint.name;

import { DashboardGrid, type DashboardGridLayoutChangeDetail, type DashboardItem } from '@absoluteui/components/dashboard-grid';
import { Button } from '@absoluteui/components/button';

const items: DashboardItem[] = [
  { id: 'kpi', x: 0, y: 0, w: 4, h: 2, label: 'Revenue' },
  { id: 'chart', x: 4, y: 0, w: 8, h: 4, minW: 4 },
  { id: 'notice', x: 0, y: 2, w: 4, h: 2, locked: true },
];
let saved: Record<string, DashboardItem[]> = {};

const host = document.querySelector<HTMLElement>('#dashboard');
if (host) {
  const grid = DashboardGrid.create(host, { label: 'Operations', items, layouts: saved, editable: true, rowHeight: 96 });
  host.addEventListener('aui-layout-change', (event) => {
    const { layouts } = (event as CustomEvent<DashboardGridLayoutChangeDetail>).detail;
    saved = layouts;
  });
  const undo = document.createElement('button');
  undo.type = 'button';
  undo.textContent = 'Undo layout change';
Button.enhance(undo);
  undo.addEventListener('click', () => {
    grid.undo();
  });
  const done = document.createElement('button');
  done.type = 'button';
  done.textContent = 'Done editing';
Button.enhance(done, { variant: 'primary' });
  done.addEventListener('click', () => {
    grid.setEditable(false);
  });
  host.before(undo, done);
}

import { DashboardCatalog, DashboardGrid, type DashboardCatalogAddDetail, type DashboardTemplate } from '@absoluteui/components/dashboard-grid';
import { DashboardWidget } from '@absoluteui/components/dashboard-widget';

const catalogHost = document.createElement('div');
const gridHost = document.createElement('div');
document.body.append(catalogHost, gridHost);

const grid = DashboardGrid.create(gridHost, { label: 'My dashboard', items: [], editable: true });
const templates: DashboardTemplate[] = [
  { id: 'kpi', label: 'KPI', description: 'A single metric', w: 3, h: 2 },
  { id: 'chart', label: 'Chart', description: 'A trend over time', w: 6, h: 4, minW: 4 },
];
DashboardCatalog.create(catalogHost, {
  grid,
  label: 'Widgets',
  templates,
  create: (template, item) => {
    const section = document.createElement('section');
    DashboardWidget.create(section, { title: template.label, removable: true });
    section.addEventListener('aui-remove', () => {
      grid.removeItem(item.id);
    });
    return section;
  },
});
// At most four charts: veto further additions.
catalogHost.addEventListener('aui-catalog-add', (event) => {
  const { template } = (event as CustomEvent<DashboardCatalogAddDetail>).detail;
  if (template.id === 'chart' && grid.items.filter((i) => i.id.startsWith('chart-')).length >= 4) event.preventDefault();
});

import { adaptLayout, compactLayout, findFreeSpot, resolveLayout, sortLayout, type DashboardItem } from '@absoluteui/components/dashboard-grid';

const layout: DashboardItem[] = [
  { id: 'a', x: 0, y: 0, w: 6, h: 2 },
  { id: 'b', x: 6, y: 0, w: 6, h: 2 },
  { id: 'c', x: 0, y: 2, w: 12, h: 1 },
];
// Move c to the top-left at half width: a is pushed down, then the layout is compacted.
const moved = compactLayout(resolveLayout(layout, { id: 'c', x: 0, y: 0, w: 6, h: 1 }, 12));
const spot = findFreeSpot(moved, 4, 1, 12);
const phone = adaptLayout(moved, 12, 1);
const readingOrder = sortLayout(phone).map((item) => item.id);
document.body.dataset.summary = `${String(spot.x)},${String(spot.y)} ${readingOrder.join(' ')}`;
